const items = $input.all();
const results = [];

for (const item of items) {
  const url = item.json['URL'] || '';

  // Extrair slug da URL
  // Ex: https://salesesantos.adv.br/advogado-trabalhista-em-sao-paulo/
  let slug = url.replace(/\/$/, '').split('/').pop();

  // Extrair cidade do slug (após 'em-')
  let cidade = '';
  const matchCidade = slug.match(/em-(.+)$/);
  if (matchCidade) {
    cidade = matchCidade[1]
      .split('-')
      .map(p => p.charAt(0).toUpperCase() + p.slice(1))
      .join(' ');
  }

  results.push({
    json: {
      ...item.json,
      slug: slug,
      cidade: cidade,
      promocao: item.json['Promoção (%)'] || item.json['Promocao'] || '0',
      url_original: url,
      row_number: item.json['row_number'] || items.indexOf(item) + 2
    }
  });
}

return results;

const items = $input.all();
const results = [];

for (const item of items) {
  const posts = item.json;
  const post = Array.isArray(posts) ? posts[0] : posts;

  if (!post || !post.id) {
    results.push({
      json: {
        erro: 'Post não encontrado',
        slug: item.json.slug || 'desconhecido'
      }
    });
    continue;
  }

  const tituloAtual = post.title?.rendered || '';
  const descricaoAtual = post.excerpt?.rendered?.replace(/<[^>]*>/g, '').trim() || '';
  const conteudo = post.content?.rendered?.replace(/<[^>]*>/g, '').substring(0, 500) || '';
  const prevData = $('Extrair Slug e Cidade').first().json;
  const cidade = prevData?.cidade || '';
  const promocao = prevData?.promocao || '0';

  // Montar body do Gemini aqui para evitar problemas com caracteres especiais no JSON
  const geminiBody = {
    systemInstruction: {
      parts: [{
        text: 'Você é um especialista em marketing jurídico e SEO. Seu trabalho é reformular títulos e meta descriptions de artigos de um escritório de advocacia para incluir promoções vigentes.\n\nRegras:\n1. O título deve ser atrativo, profissional e incluir a promoção de forma natural\n2. O título deve manter a palavra-chave principal (área jurídica + cidade)\n3. A meta description deve ter entre 140-160 caracteres\n4. A meta description deve incluir a promoção e um call-to-action\n5. Mantenha o tom profissional - é um escritório de advocacia\n6. Use a promoção de forma elegante, sem parecer apelativo\n\nResponda SEMPRE em formato JSON com esta estrutura exata:\n{\n  "novo_titulo": "...",\n  "nova_descricao": "..."\n}'
      }]
    },
    contents: [{
      role: 'user',
      parts: [{
        text: `Reformule o título e a descrição deste artigo do escritório Sales e Santos Advogados:\n\nTítulo atual: ${tituloAtual}\nDescrição atual: ${descricaoAtual}\nCidade: ${cidade}\nPromoção vigente: ${promocao}% de desconto\n\nContexto do artigo (primeiros 500 caracteres):\n${conteudo}\n\nGere o novo título e nova descrição em formato JSON.`
      }]
    }],
    generationConfig: {
      temperature: 0.7,
      maxOutputTokens: 500,
      responseMimeType: 'application/json'
    }
  };

  results.push({
    json: {
      post_id: post.id,
      titulo_atual: tituloAtual,
      descricao_atual: descricaoAtual,
      conteudo_resumo: conteudo,
      slug: prevData?.slug || '',
      cidade: cidade,
      promocao: promocao,
      url_original: prevData?.url_original || '',
      row_number: prevData?.row_number || 0,
      geminiBody: geminiBody
    }
  });
}

return results;

const items = $input.all();
const results = [];

for (const item of items) {
  let novoTitulo = '';
  let novaDescricao = '';

  try {
    // Extrair texto da resposta do Gemini
    // Formato: { candidates: [{ content: { parts: [{ text: '...' }] } }] }
    const candidates = item.json.candidates || [];
    const textoParts = candidates[0]?.content?.parts || [];
    let resposta = textoParts[0]?.text || '';

    // Procurar JSON na resposta
    const jsonMatch = resposta.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      const parsed = JSON.parse(jsonMatch[0]);
      novoTitulo = parsed.novo_titulo || '';
      novaDescricao = parsed.nova_descricao || '';
    }
  } catch (e) {
    // Fallback: tentar pegar qualquer texto da resposta
    const fallback = item.json.candidates?.[0]?.content?.parts?.[0]?.text || '';
    novoTitulo = fallback.substring(0, 100);
    novaDescricao = fallback.substring(0, 160);
  }

  const prevData = $('Preparar Dados para IA').first().json;

  results.push({
    json: {
      post_id: prevData?.post_id || item.json.post_id,
      novo_titulo: novoTitulo,
      nova_descricao: novaDescricao,
      titulo_anterior: prevData?.titulo_atual || '',
      url_original: prevData?.url_original || '',
      row_number: prevData?.row_number || 0,
      cidade: prevData?.cidade || '',
      promocao: prevData?.promocao || '0'
    }
  });
}

return results;
